INSERT INTO knowledge_chunk (file_id, seq, content, embedding) VALUES ('1', '1', 'Java 基础开发规范。第一，命名规范：类名采用大驼峰，方法名与变量名采用小驼峰，常量全部大写并使用下划线分隔，避免使用拼音缩写。第二，集合使用原则：优先使用 ArrayList 与 HashMap，需要保证元素有序时使用 LinkedList 与 LinkedHashMap，需要线程安全时使用 ConcurrentHashMap 而不是给 HashMap 加锁。第三，字符串处理：大量拼接字符串时使用 StringBuilder，避免在循环中使用加号拼接；字符串比较必须使用 equals 方法而不能使用双等号。第四，异常处理：不要捕获异常后吞掉不处理，至少要记录日志；方法抛出受检异常时调用方必须处理或继续抛出。第五，空值防护：接收外部参数时使用 Objects.requireNonNull 或显式判空，避免空指针异常。第六，循环优化：不要在循环体内重复创建对象或查询数据库，尽量把可以复用的计算提到循环外。', '[-0.061768558,0.006965641,-0.08617773,0.06369147,-0.043677513,-0.061022937,0.019464552,0.038968347,-0.065064974,-0.036790356,-0.06636,0.037791055,-0.029255692,-0.01274418,0.018728744,0.015599111,0.021779891,0.03257173,0.014755386,0.013479987,-0.00078547414,0.02008263,-0.010193381,-0.004245607,0.016374161,0.005807971,-0.07723032,-0.051565364,0.07605302,-0.012508721,0.025252901,0.014058822,0.03800689,-0.010291489,-0.008005582,-0.021524811,0.012184966,-0.010644677,-0.084294066,0.0053762975,-0.035357986,0.03449464,-0.018336315,-0.013784121,0.072207205,0.00052058353,-0.012116291,-0.05576437,0.012547964,0.0055038375,-0.0089326985,-0.005013299,0.060983695,-0.04395221,0.034788962,0.020249413,0.0234281,-0.06812593,-0.025135173,0.021407083,-0.04556118,0.0702843,-0.033356592,0.0414799,0.020013954,-0.033945236,0.012734369,-0.051172934,-0.028941747,-0.0296285,-0.056078315,0.014902547,-0.0014323712,0.005047637,-0.025586467,-0.004902928,0.0024845754,-0.037241653,-0.030236768,-0.02923607,0.027882185,0.0340041,0.043363567,-0.012292884,0.013676202,0.033140752,0.02884364,0.030962765,0.015157627,-0.015716841,0.052154012,-0.085706815,0.009300603,-0.0075886245,0.0056215664,0.05874684,0.005189893,0.030236768,0.008069351,0.041401416,-0.030688062,-0.01710997,0.031865355,-0.008957226,0.039812073,-0.030688062,0.037280895,-0.009987355,0.011743482,-0.038713265,0.011959319,-0.014431631,0.032807186,-0.016805835,0.014833872,-0.020445628,-0.026057383,-0.012155534,0.035397228,-0.008162554,-0.006465292,-0.023133777,