INSERT INTO knowledge_chunk (file_id, seq, content, embedding) VALUES ('2', '1', 'Spring Boot 企业开发规范。第一，工程结构：按 controller、service、mapper、entity、config 分包，业务逻辑写在 service 层，controller 只做参数校验与结果封装，不允许在 controller 中写 SQL。第二，配置管理：数据库密码、第三方密钥等敏感配置必须放在环境变量或配置中心，不能明文写在配置文件中；不同环境通过 application-prod.yml 等 profile 区分。第三，接口设计：RESTful 接口使用统一的返回结构 Result，成功返回 code 200，业务失败返回业务码并附带提示信息；所有接口必须做参数校验，使用 JSR 303 注解。第四，事务管理：涉及多表写入的操作必须加事务注解，注意事务失效的场景，例如自调用、方法不是 public、异常被捕获。第五，性能建议：合理使用缓存减少数据库压力，批量操作使用批量接口，避免循环调用远程接口。第六，安全要求：登录鉴权使用 JWT，接口通过注解控制权限，用户输入必须做防注入处理。', '[-0.09168066,0.006541797,-0.087020226,0.04041589,-0.03892608,-0.06681228,0.029490612,0.00837541,-0.007950433,0.004791747,-0.025517784,0.08037338,0.032623034,-0.028612006,0.05856102,-0.024658278,0.051646773,0.011660634,0.02358867,0.014181852,0.010724727,-0.019654041,0.011173581,0.02089555,0.015767163,0.003110935,-0.04878175,-0.027351396,0.03331064,-0.0057921167,0.059974432,7.054367e-05,0.037245266,-0.026721092,-0.006680273,-0.06685048,0.023416769,0.005295513,-0.10039032,0.017314274,-0.02095285,-0.01674127,0.018536683,-0.046260532,0.05416799,-0.014411054,-0.028612006,-0.0553904,0.019157438,0.022652762,-0.041409098,0.015834013,0.017925479,-0.0413709,0.045381926,0.033578042,0.026148088,-0.014172302,-0.04477072,0.040606894,-0.08625622,0.050729964,-0.022079758,0.0054626395,-0.0004951114,-0.0035072628,0.025517784,-0.06719428,-0.022156158,-0.054779194,-0.034342047,-0.015098658,-0.00966467,0.0037078143,-0.05428259,0.0071386765,0.04614593,0.02091465,-0.013360546,-0.0043572187,0.024734678,0.012672941,0.03730257,0.036825065,0.03224103,-0.023263967,-0.0053575886,-0.0052047875,0.02519308,0.016330617,0.043930314,-0.058866624,-0.00980792,-0.03760817,-0.056421805,0.030331017,0.008552087,0.04419772,0.002097434,0.02225166,-0.031056823,-0.0017572127,0.021888757,-0.049354754,0.03770367,0.008079358,0.077699356,-0.03457125,0.028382804,-0.034093745,0.014697555,0.004118467,0.019921442,-0.00022621725,-0.024409976,-0.036614962,0.0018419694,0.024161674,-