INSERT INTO knowledge_chunk (file_id, seq, content, embedding) VALUES ('3', '1', 'Redis 缓存使用规范。第一，缓存穿透应对：对于查询不存在的数据，可以缓存空值或使用布隆过滤器拦截，避免每次都打穿到数据库。第二，缓存击穿应对：热点 key 过期瞬间有大量请求同时落到数据库，可以使用互斥锁重建缓存，或使用逻辑过期与后台刷新。第三，缓存雪崩应对：大量 key 在同一时间过期导致数据库压力骤增，可以在过期时间上增加随机值，避免同一时刻集体失效；同时设置合理的缓存重建限流。第四，缓存一致性：写数据时采用 Cache Aside 模式，先更新数据库再删除缓存；对一致性要求高的场景可以使用延迟双删或消息队列异步删除缓存。第五，内存与过期策略：为每个 key 设置合理的过期时间，避免内存无限增长；根据业务选择 allkeys-lru 等内存淘汰策略。第六，监控告警：缓存命中率、内存使用率需要纳入监控，命中率明显下降时及时排查。', '[-0.013323026,0.020919986,-0.04720698,0.041575402,-0.088971354,-0.07113173,0.04187777,0.06788129,0.007847357,0.009642658,-0.033392604,0.0042118714,0.015288409,0.0741554,0.054274797,-0.016204957,0.043956537,0.003533909,-0.018850664,-0.024075937,0.032655586,0.043805353,-0.007086716,-0.0030756348,0.039458834,0.052196026,-0.015260062,-0.0033307564,0.0931289,0.045884125,0.058432337,0.015798653,-0.051666886,-0.023338918,0.02413263,0.017206546,-0.0091513125,-0.02946184,-0.07619637,0.008759181,0.010072586,-0.009902504,0.031030368,-0.014882104,0.054614957,-0.041802175,0.017849075,-0.04187777,-0.0027425592,-0.03681313,-0.06727656,0.012160805,0.03490444,-0.08783748,0.030973673,0.06357257,0.0046299878,-0.05189366,0.009836362,-0.005830005,-0.017924666,-0.01971052,-0.025077526,-0.012226948,0.028271273,0.04675343,0.013975004,-0.012671048,-0.017508913,-0.10235108,-0.00014889486,0.05136452,-0.0361517,0.023376714,-0.051855862,-0.01997509,-0.00042786048,-0.002066959,0.005494567,-0.018104197,0.04501482,0.011272603,0.006401667,0.034035135,-0.026910624,0.024472792,-0.012009622,0.02666495,0.064328484,-0.017603403,0.059868578,-0.033505995,-0.03292016,-0.08216811,0.021751493,0.052271616,-0.011905683,0.021921575,0.095925786,0.016148264,0.018548299,-0.030841388,-0.036454067,-0.012595457,0.08609887,0.0013417515,0.07162308,0.040819485,-0.023697978,0.0019925484,0.016686855,0.0069544306,-0.018964052,0.002584289,-0.019805009,-0.048038486,-0.051969253,-0.01906799,-0.03091698,-0.010526136,0.029858697,0.03118155,0.016696302,-0.04936134,-0.009311945,0.