INSERT INTO knowledge_chunk (file_id, seq, content, embedding) VALUES ('4', '1', 'MySQL 性能优化规范。第一，索引设计：为高频查询条件的字段建立索引，遵循最左前缀原则；使用覆盖索引减少回表；联合索引把区分度高的字段放在前面；避免在索引列上进行函数运算或隐式类型转换，否则索引失效。第二，SQL 优化：查询尽量只取需要的字段，避免 select 星号；分页查询大偏移量时使用延迟关联或游标方式优化；使用 explain 分析执行计划，重点关注 type、key、rows 字段。第三，事务与锁：事务保持短小，避免长事务；避免在事务中做远程调用和慢查询，减少锁等待；合理使用索引减少行锁范围。第四，慢查询治理：开启慢查询日志，定期分析慢 SQL；对执行时间超过阈值的语句进行索引优化或 SQL 改写。第五，容量规划：监控连接数、磁盘空间、内存使用；为高频表预留扩容空间，避免高峰期出现资源瓶颈。第六，数据归档：历史数据定期归档到历史表，保持主表行数可控，提升查询效率。', '[-0.047190543,-0.018034482,-0.06002607,0.040829916,-0.040829916,-0.047304805,0.0044443477,0.011835724,0.007236645,0.045438513,-0.053513087,0.01396863,-0.024528418,0.054008227,0.0362594,-0.023861885,0.025404433,-0.00025128893,0.018215397,-0.013025962,-0.02523304,0.02178611,0.055341292,0.04140123,0.012454648,0.052065756,-0.034678765,0.0012878372,0.09118173,0.061473396,0.029632159,0.015882531,0.05122783,-0.027899172,0.0019269949,-0.037097327,-0.030108253,-0.048752137,-0.065624945,0.03591661,0.0032326856,0.020072168,0.026204273,0.002468553,0.050504167,-0.021595674,0.003908741,-0.042620033,-0.022890652,-0.034640677,-0.0006278504,-0.0043348456,-0.008998197,-0.04646688,0.055188943,0.031612713,-0.02949885,-0.020719659,-0.02348101,0.009398117,-0.021938462,0.03420267,-0.036468882,-0.025023557,0.005327504,0.056407746,0.0002722669,-0.004601459,-0.010312219,-0.07507067,-0.03675454,0.08325951,-0.013863889,-0.026661325,-0.05473189,0.00911246,0.033021953,-0.010036084,0.0095885545,-0.0396492,0.027632559,0.0194342,-0.0045752735,0.02449033,-0.028432399,0.037173502,0.0039063604,-0.01041696,0.025575828,0.018234441,0.054769978,-0.06273029,-0.028051522,-0.06432997,0.049056835,0.0046728733,-0.0026851762,0.03690689,0.08044103,-0.014130502,0.009179113,-0.0067177014,0.015844444,-0.031955503,0.088058546,-0.01577779,0.057436112,0.029137019,-0.000605831,-0.026966026,0.0059416667,0.0102931755,-0.007484215,-0.015187433,-0.019319938,-0.0879062,-0.0066415262,0.04532425,0.016368149,-0.028013434,0.036545057,-0.037478205,0.02538539,