INSERT INTO knowledge_chunk (file_id, seq, content, embedding) VALUES ('5', '1', '软件测试流程规范。第一，测试流程：需求评审、测试计划、用例设计、用例评审、执行测试、缺陷跟踪、回归测试、测试报告，每个阶段都要有输出物。第二，用例设计方法：等价类划分把输入域划分为有效与无效等价类，边界值分析覆盖边界及边界附近取值，场景法覆盖正常流程与异常流程，判定表与因果图用于复杂条件组合。第三，用例要素：每条用例必须包含用例编号、前置条件、测试步骤、测试数据、预期结果与优先级，预期结果要可验证、不模糊。第四，缺陷管理：缺陷按严重程度划分为致命、严重、一般、轻微四级，按优先级决定修复顺序；缺陷报告要包含复现步骤、实际结果、预期结果与环境信息。第五，回归测试：每次修复缺陷或版本变更后都要执行回归测试，优先覆盖核心功能与历史缺陷用例。第六，验收标准：以需求规格说明书为准，功能全部实现、无致命与严重缺陷、缺陷率低于阈值才能判定测试通过。', '[-0.089878224,0.008418788,-0.03167137,-0.01982379,-0.039530855,-0.023617351,-0.006249649,0.060852613,-0.04525038,0.013267738,-0.037001815,0.05058082,0.038519237,0.03404478,0.028675433,0.004430685,0.016292859,-0.021535756,0.03501749,-0.061047155,-0.0012985652,-0.009498494,0.05859593,-0.02085486,0.011565498,0.025523858,-0.06773939,-0.046923436,0.07085205,0.01615668,0.000115965035,-0.001364223,0.010116164,-0.028189078,-0.049997192,-0.024940234,0.0052185785,-0.047662694,-0.046261992,0.012800838,0.010077255,-0.03141847,-0.008953777,-0.029901044,0.03221609,-0.01828691,0.012839746,-0.07357563,-0.009970257,0.010223161,-0.008175611,-0.0006748162,0.06423764,-0.08575394,0.065716155,0.049063392,0.031107202,-0.037429806,-0.07217494,0.032994255,-0.029764865,0.042215526,-0.009138592,-0.015835686,0.03324716,-0.027372004,0.00040306587,-0.039025046,-0.022644643,-0.04742924,-0.01762547,0.034667313,0.004070783,0.01715857,-0.06972371,0.015028339,0.022936456,-0.032254998,0.0022700573,-0.01828691,-0.013102377,0.019668156,-0.014182083,0.013793,-0.019337436,-0.044550028,0.0013763818,0.05653379,0.008146429,-0.016020501,0.024531696,-0.023675714,0.0032828895,-0.025893487,-0.05820685,0.012509025,-0.03674891,0.0006760321,0.03408369,0.013831908,-0.010028619,0.016146952,0.028325258,-0.03482295,0.0107192425,-0.00674573,0.07707738,0.0078011183,-0.0024196112,-0.02141903,0.01199349,0.03898614,0.013880543,-0.002306534,0.002526609,-0.01066088,-0.0073099006,-0.024142614,0.02641875,0.0043553,0.03844142,-0.0334417,0.055677805,-0.04237116,-0.007791391,-0.0207