INSERT INTO knowledge_chunk (file_id, seq, content, embedding) VALUES ('6', '1', 'Linux 运维操作手册。第一，常用命令：使用 ps 与 top 查看进程，使用 netstat 或 ss 查看端口，使用 df 与 du 查看磁盘，使用 free 查看内存，使用 systemctl 管理服务。第二，服务部署：生产环境服务使用 systemd 托管，编写 Unit 文件配置启动、停止、开机自启与异常自动重启；nginx 作为反向代理配置负载均衡与 HTTPS 证书。第三，日志排查：应用日志统一输出到 /var/log 下，排障顺序是先看系统日志 journalctl 再看应用日志，定位异常堆栈与错误码；日志要带时间戳与请求编号便于关联。第四，权限与安全：root 权限最小化使用，普通操作使用普通用户配合 sudo；敏感文件权限收紧；定期更新安全补丁。第五，监控告警：对 CPU、内存、磁盘、网络与关键服务设置监控与告警阈值，出现异常及时通知值班人员。第六，备份策略：核心数据每日全量备份，日志等非关键数据保留合理天数；备份定期演练恢复流程，确保可还原。', '[-0.09878701,-0.0035603514,-0.048461553,0.027512027,-0.06046045,-0.061353568,0.04104476,-0.013163836,-0.014319069,0.025725784,-0.0029706,-0.005683942,0.013348284,0.056654975,0.047762588,-0.022172714,0.05886836,0.007722589,-0.007300298,-0.056654975,0.012134804,-0.022677522,0.028346902,0.09754441,0.03677331,0.051723387,-0.012309546,-0.05036429,0.06632399,0.03964683,0.017114928,-0.05203404,0.007441062,0.0076643424,-0.0217844,0.010435931,-0.026444165,0.028075082,-0.0850407,0.005150011,-0.0142219905,0.000775414,0.03073503,-0.00091496424,0.032967836,-0.003921969,0.021823231,-0.026890725,-0.0002932072,-0.0063489294,-0.03335615,0.010280606,0.014959786,-0.056926794,-0.006751805,0.03578311,0.0102903135,-0.06927517,0.0024949156,0.03209413,-0.058091734,0.033142578,-0.08434174,0.002031366,0.036831558,0.056266658,-0.0038564408,0.0040554516,-0.0025919941,-0.035938434,-0.050830267,0.022114467,0.0010405595,0.013241498,-0.040617615,0.028327487,0.05517938,-0.044034775,0.03883137,-0.047568433,0.018260453,0.044617247,0.012134804,0.038520724,-0.0058295596,0.016648952,0.03743344,0.037666433,0.041627232,0.003397745,-0.0018748272,-0.07374078,-0.02768677,-0.05510172,-0.01891088,0.0053635836,-0.008834138,-0.0047471356,0.044772573,0.010154404,0.009902,-0.013212374,0.02021173,-0.019978741,0.049238183,0.036384996,0.045976344,0.0009883798,-0.006678996,-0.008819575,0.020231145,0.0004947966,-0.043646462,0.013396824,-0.030890357,-0.04982065,-0.0072663208,-0.04613167,-0.017784769,-0.01